using System;using System.IO;using System.Linq;using System.Text;using System.Globalization;using BeamScheduleFormatter;
class SlabFormatterTests {
 static int checks;static void Check(bool value,string message){if(!value)throw new Exception(message);checks++;}
 static string Fixture(int count,bool identical){var b=new StringBuilder("0\nSECTION\n2\nENTITIES\n");Action<double,double,string> t=(x,y,text)=>b.Append("0\nTEXT\n10\n"+x.ToString("R",CultureInfo.InvariantCulture)+"\n20\n"+y.ToString("R",CultureInfo.InvariantCulture)+"\n1\n"+text+"\n");t(0,15000,"SLAB SCHEDULE");t(5000,9700,"FULL LENGTH");t(11000,9700,"FULL LENGTH");for(int r=0;r<count;r++){double y=8000-r*700;t(200,y+250,"S"+(r+1));t(3000,y,"125");for(int c=0;c<9;c++)t(5000+c*3000,y,c==1||c==3?"---":"#10@"+(identical?175:100+r)+" C/C");}return b.Append("0\nENDSEC\n0\nEOF\n").ToString();}
 static void Main(){var merged=SlabFormatter.Build(Fixture(4,true),"2S","SECOND FLOOR",true);Check(merged.Groups.Count==1&&merged.Groups[0].Originals=="S1, S2, S3, S4","Identical rows not grouped/source marks lost");Check(merged.Groups[0].Mark=="2S-001","Three-digit prefix numbering");Check(merged.Drawing.ModelEntities().Any(e=>e.Type=="HATCH"&&e.Get(8)=="Hatch 80"),"Template header hatch missing");var rows=SlabScheduleReader.Read(Serialize(merged.Drawing));Check(rows.Count==1&&rows[0].Mark=="2S-001"&&rows[0].Bars[0].SpacingMm==175,"Revised DXF not usable by estimator");var split=SlabFormatter.Build(Fixture(4,true),"3S","THIRD FLOOR",false);Check(split.Groups.Count==4&&split.Groups.Last().Mark=="3S-004","Merge-off or floor prefix failed");var many=SlabFormatter.Build(Fixture(60,false),"2S","SECOND FLOOR",true);Check(many.Groups.Count==60,"Additional rows lost");Check(SlabFormatter.ReadRevised(many.Drawing).Count==60,"Extended export rows unreadable");var mark=many.Drawing.ModelEntities().First(e=>SlabFormatter.Plain(e)=="2S-060");var lastLine=many.Drawing.ModelEntities().Where(e=>e.Type=="LINE").Min(e=>Math.Min(e.Num(20),e.Num(21)));Check(lastLine<mark.Num(20),"Borders do not extend to last row");Check(merged.Drawing.ModelEntities().Any(e=>SlabFormatter.Plain(e)=="SECOND FLOOR"),"Floor title not updated");Check(merged.Drawing.ModelEntities().Any(e=>SlabFormatter.Plain(e)=="ORIGINAL SLAB MARKS"),"Right-side mapping header missing");var right=merged.Drawing.ModelEntities().Where(e=>e.Type=="LINE").Max(e=>Math.Max(e.Num(10),e.Num(11)));Check(merged.Drawing.ModelEntities().First(e=>SlabFormatter.Plain(e)=="S1, S2, S3, S4").Num(10)>right,"Original slab marks are inside table borders");Check(merged.Drawing.ModelEntities().Where(e=>e.Type=="MTEXT"&&e.Num(20)<158).All(e=>!e.Get(7).Contains("B")),"Body text is bold");var original=SlabScheduleReader.Read(Fixture(3,true));original[1].Bars=(SlabBar[])original[1].Bars.Clone();original[1].Bars[8]=new SlabBar{Diameter=12,SpacingMm=175};original[2].Thickness=150;Check(SlabFormatter.Group(original,"2S",true).Count==3,"Different dia/thickness merged");/* ACI option: the MNL-66 slab schedules, one-way / two-way by the bars, read back unchanged */{var aciBuilt=SlabFormatter.Build(Fixture(4,false),"2S","SECOND FLOOR",false);aciBuilt.Drawing=AciSlabSchedule.Build(aciBuilt,"SECOND FLOOR");var aciText=Serialize(aciBuilt.Drawing);Check(aciText.Contains("CONCRETE SLAB SCHEDULE"),"ACI slab schedule title");string aciPath=System.IO.Path.Combine(System.IO.Path.GetTempPath(),"AciSlab-"+Guid.NewGuid().ToString("N")+".dxf");try{SlabFormatter.Export(aciBuilt,aciPath);var back=SlabScheduleReader.Read(System.IO.File.ReadAllText(aciPath));Check(back.Count==aciBuilt.Groups.Count&&back.Select(SlabFormatter.Signature).SequenceEqual(aciBuilt.Groups.Select(g=>SlabFormatter.Signature(g.Schedule))),"ACI slab schedule reads back unchanged");}finally{if(System.IO.File.Exists(aciPath))System.IO.File.Delete(aciPath);}}
Console.WriteLine("PASS: "+checks+" slab formatter grouping, three-digit numbering, original mapping, regular text, floor title, 60-row extension and estimator round-trip checks.");}
 static string Serialize(Dxf d){var b=new StringBuilder();foreach(var e in d.Records)foreach(var p in e.P)b.Append(p.Code).Append('\n').Append(p.Value).Append('\n');return b.ToString();}
}
